        (TDEFL_LZ_CODE_BUF_SIZE as c_int - 8 as c_int) as isize,
    ) as *mut mz_uint8
    || (*d).m_total_lz_bytes
        > (31 as c_int * 1024 as c_int) as mz_uint
            && (((*d)
