                as c_long as mz_uint)
                .wrapping_mul(115 as mz_uint)
                >> 7 as c_int
                >= (*d).m_total_lz_bytes
                || (*d).m_flags & TDEFL_FORCE_ALL_RAW_BLOCKS as c_int as mz_uint
                    != 0)
{
    let mut n: c_int = 0;
    (*d).m_pSrc = pSrc;
    (*d).m_src_buf_left = src_buf_left;
